message.content:
```st
FUNCTION_BLOCK FB
VAR_INPUT
    ipText : STRING(254);
END_VAR
VAR_OUTPUT
    ipValue : UDINT;
END_VAR
VAR
    i           : INT;
    segmentCount: INT;
    segmentValue: INT;
    digitCount  : INT;
    firstIsZero : BOOL;
    isValid     : BOOL;
    ch          : CHAR;
    dotCount    : INT;
    segValues   : ARRAY[0..3] OF INT;
END_VAR

(* Initialisation *)
ipValue      := 0;
isValid      := TRUE;
segmentCount := 0;
segmentValue := 0;
digitCount   := 0;
firstIsZero  := FALSE;
dotCount     := 0;

(* Scan the input string character by character *)
FOR i := 1 TO LEN(ipText) DO
    ch := MID(ipText, 1, i);

    IF ch = '.' THEN
        (* End of a segment *)
        IF digitCount = 0 THEN
            isValid := FALSE;
        END_IF;

        IF firstIsZero AND (digitCount > 1) THEN
            isValid := FALSE;
        END_IF;

        IF segmentValue > 255 THEN
            isValid := FALSE;
        END_IF;

        (* Store the parsed segment *)
        segValues[segmentCount] := segmentValue;
        segmentCount := segmentCount + 1;

        (* Prepare for the next segment *)
        segmentValue := 0;
        digitCount   := 0;
        firstIsZero  := FALSE;

        dotCount := dotCount + 1;
        IF dotCount > 3 THEN
            isValid := FALSE;
        END_IF;

    ELSE
        (* Must be a decimal digit *)
        IF (ch >= '0') AND (ch <= '9') THEN
            segmentValue := segmentValue * 10 + (BYTE_TO_INT(CHAR_TO_BYTE(ch)) - 48);
            digitCount   := digitCount + 1;

            (* Detect leading zero *)
            IF digitCount = 1 AND ch = '0' THEN
                firstIsZero := TRUE;
            END_IF;

            (* Reject additional digits after a leading zero *)
            IF firstIsZero AND (digitCount > 1) THEN
                isValid := FALSE;
            END_IF;

            (* Early overflow detection *)
            IF segmentValue > 255 THEN
                isValid := FALSE;
            END_IF;
        ELSE
            isValid := FALSE;
        END_IF;
    END_IF;
END_FOR;

(* Process the last segment (if any) *)
IF digitCount > 0 THEN
    IF firstIsZero AND (digitCount > 1) THEN
        isValid := FALSE;
    END_IF;

    IF segmentValue > 255 THEN
        isValid := FALSE;
    END_IF;

    segValues[segmentCount] := segmentValue;
    segmentCount := segmentCount + 1;
ELSE
    (* No characters after the last dot (or empty string) → invalid *)
    IF segmentCount < 4 THEN
        isValid := FALSE;
    END_IF;
END_IF;

(* Verify the correct number of segments and dots *)
IF segmentCount <> 4 THEN
    isValid := FALSE;
END_IF;

IF dotCount <> 3 THEN
    isValid := FALSE;
END_IF;

(* Assemble the IPv4 address in network byte order or set 0 for invalid input *)
IF isValid THEN
    ipValue := SHL(UDINT(segValues[0]), 24) OR
               SHL(UDINT(segValues[1]), 16) OR
               SHL(UDINT(segValues[2]),  8) OR
               UDINT(segValues[3]);
ELSE
    ipValue := 0;
END_IF;

END_FUNCTION_BLOCK
```

